    .apb_ext_pprot(apb_apb_ext_if.pprot), .apb_ext_prdata(apb_apb_ext_if.prdata), .apb_ext_pready(apb_apb_ext_if.pready),
    .apb_ext_pslverr(apb_apb_ext_if.pslverr),
    .venc_cfg_paddr(venc_cfg_paddr), .venc_cfg_psel(venc_cfg_psel), .venc_cfg_penable(venc_cfg_penable),
    .venc_cfg_pwrite(venc_cfg_pwrite), .venc_cfg_pwdata(venc_cfg_pwdata), .venc_cfg_pstrb(venc_cfg_pstrb),
    .venc_cfg_pprot(), .venc_cfg_prdata(venc_cfg_prdata), .venc_cfg_pready(venc_cfg_pready),
    .venc_cfg_pslverr(venc_cfg_pslverr),
    .jpeg_cfg_paddr(jpeg_cfg_paddr), .jpeg_cfg_psel(jpeg_cfg_psel), .jpeg_cfg_penable(jpeg_cfg_penable),
    .jpeg_cfg_pwrite(jpeg_cfg_pwrite), .jpeg_cfg_pwdata(jpeg_cfg_pwdata), .jpeg_cfg_pstrb(jpeg_cfg_pstrb),
    .jpeg_cfg_pprot(), .jpeg_cfg_prdata(jpeg_cfg_prdata), .jpeg_cfg_pready(jpeg_cfg_pready),
    .jpeg_cfg_pslverr(jpeg_cfg_pslverr),
    .npu_cfg_paddr(npu_cfg_paddr), .npu_cfg_psel(npu_cfg_psel), .npu_cfg_penable(npu_cfg_penable),
    .npu_cfg_pwrite(npu_cfg_pwrite), .npu_cfg_pwdata(npu_cfg_pwdata), .npu_cfg_pstrb(npu_cfg_pstrb),
    .npu_cfg_pprot(), .npu_cfg_prdata(npu_cfg_prdata), .npu_cfg_pready(npu_cfg_pready),
    .npu_cfg_pslverr(npu_cfg_pslverr),
    .qspi_xip_axi_awid(s_if[S_SPI_NOR].awid[3:0]),
