    .qspi_xip_axi_rlast(s_if[S_SPI_NOR].rlast),
    .qspi_xip_axi_rvalid(s_if[S_SPI_NOR].rvalid),
    .qspi_xip_axi_rready(s_if[S_SPI_NOR].rready),
    .irq(apb_irq)
  );
  assign s_if[S_SPI_NOR].bid[7:4] = '0;    // the NoC keeps the master ID itself
  assign s_if[S_SPI_NOR].rid[7:4] = '0;    // the NoC keeps the master ID itself

  apb_sva #(.NAME("apb_apb_ext")) u_apb_apb_ext_sva (apb_apb_ext_if);
  initial uvm_config_db#(virtual apb_if)::set(null, "uvm_test_top.env.apb_apb_ext.*", "vif", apb_apb_ext_if);

  // ---------------- RTL master venc: ipcam_venc_c1p ----------------
  ipcam_venc_c1p u_venc (
    .clk(aclk), .rst_n(aresetn),
    .awid(m_if[M_VENC].awid[ID_WIDTH-1:0]),
    .awaddr(m_if[M_VENC].awaddr),
    .awlen(m_if[M_VENC].awlen),
    .awsize(m_if[M_VENC].awsize),
    .awburst(m_if[M_VENC].awburst),
    .awvalid(m_if[M_VENC].awvalid),
    .awready(m_if[M_VENC].awready),
    .wdata(m_if[M_VENC].wdata),
    .wstrb(m_if[M_VENC].wstrb),
    .wlast(m_if[M_VENC].wlast),
    .wvalid(m_if[M_VENC].wvalid),
    .wready(m_if[M_VENC].wready),
    .bid(m_if[M_VENC].bid[ID_WIDTH-1:0]),
    .bresp(m_if[M_VENC].bresp),
    .bvalid(m_if[M_VENC].bvalid),
    .bready(m_if[M_VENC].bready),
    .arid(m_if[M_VENC].arid[ID_WIDTH-1:0]),
    .araddr(m_if[M_VENC].araddr),
    .arlen(m_if[M_VENC].arlen),
    .arsize(m_if[M_VENC].arsize),
    .arburst(m_if[M_VENC].arburst),
    .arvalid(m_if[M_VENC].arvalid),
    .arready(m_if[M_VENC].arready),
    .rid(m_if[M_VENC].rid[ID_WIDTH-1:0]),
    .rdata(m_if[M_VENC].rdata),
    .rresp(m_if[M_VENC].rresp),
    .rlast(m_if[M_VENC].rlast),
    .rvalid(m_if[M_VENC].rvalid),
    .rready(m_if[M_VENC].rready),
