  assign m_if[M_VENC].arid[7:ID_WIDTH] = '0;
  assign m_if[M_VENC].awlock = 1'b0;
  assign m_if[M_VENC].arlock = 1'b0;
  assign m_if[M_VENC].awcache = 4'h0;
  assign m_if[M_VENC].arcache = 4'h0;
  assign m_if[M_VENC].awprot = 3'h0;
  assign m_if[M_VENC].arprot = 3'h0;

