    .wdata(m_if[M_JPEG].wdata),
    .wstrb(m_if[M_JPEG].wstrb),
    .wlast(m_if[M_JPEG].wlast),
    .wvalid(m_if[M_JPEG].wvalid),
    .wready(m_if[M_JPEG].wready),
    .bid(m_if[M_JPEG].bid[ID_WIDTH-1:0]),
    .bresp(m_if[M_JPEG].bresp),
    .bvalid(m_if[M_JPEG].bvalid),
    .bready(m_if[M_JPEG].bready),
    .arid(m_if[M_JPEG].arid[ID_WIDTH-1:0]),
    .araddr(m_if[M_JPEG].araddr),
    .arlen(m_if[M_JPEG].arlen),
    .arsize(m_if[M_JPEG].arsize),
    .arburst(m_if[M_JPEG].arburst),
    .arvalid(m_if[M_JPEG].arvalid),
    .arready(m_if[M_JPEG].arready),
    .rid(m_if[M_JPEG].rid[ID_WIDTH-1:0]),
    .rdata(m_if[M_JPEG].rdata),
