    .rlast(m_if[M_JPEG].rlast),
    .rvalid(m_if[M_JPEG].rvalid),
    .rready(m_if[M_JPEG].rready),
    .psel(jpeg_cfg_psel), .penable(jpeg_cfg_penable), .pwrite(jpeg_cfg_pwrite),
    .paddr(jpeg_cfg_paddr[11:0]), .pwdata(jpeg_cfg_pwdata), .pstrb(jpeg_cfg_pstrb),
    .pready(jpeg_cfg_pready), .prdata(jpeg_cfg_prdata), .pslverr(jpeg_cfg_pslverr)

  );
  assign m_if[M_JPEG].awid[7:ID_WIDTH] = '0;
  assign m_if[M_JPEG].arid[7:ID_WIDTH] = '0;
  assign m_if[M_JPEG].awlock = 1'b0;
  assign m_if[M_JPEG].arlock = 1'b0;
  assign m_if[M_JPEG].awcache = 4'h0;
  assign m_if[M_JPEG].arcache = 4'h0;
  assign m_if[M_JPEG].awprot = 3'h0;
  assign m_if[M_JPEG].arprot = 3'h0;

  // ---------------- RTL master npu: ipcam_npu_xj ----------------
  ipcam_npu_xj u_npu (
    .clk(aclk), .rst_n(aresetn),
    .awid(m_if[M_NPU].awid[ID_WIDTH-1:0]),
    .awaddr(m_if[M_NPU].awaddr),
    .awlen(m_if[M_NPU].awlen),
    .awsize(m_if[M_NPU].awsize),
    .awburst(m_if[M_NPU].awburst),
    .awvalid(m_if[M_NPU].awvalid),
    .awready(m_if[M_NPU].awready),
    .wdata(m_if[M_NPU].wdata),
